begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(24);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp181@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18100000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18100000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18100000-0000-0000-0000-000000000004','18100000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18100000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18100000-0000-0000-0000-000000000005','18100000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('18100000-0000-0000-0000-000000000006','18100000-0000-0000-0000-000000000002','Synthetic client');
insert into public.staffs(id,organization_id,name) values ('18100000-0000-0000-0000-000000000007','18100000-0000-0000-0000-000000000002','Synthetic staff');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18100000-0000-0000-0000-000000000009','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp-recipient@example.invalid','x',now(),now());
insert into public.organization_members(organization_id,user_id,role) values ('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000009','member');
update public.staffs set user_id='18100000-0000-0000-0000-000000000009' where id='18100000-0000-0000-0000-000000000007';

insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18100000-0000-0000-0000-000000000008','18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000006','2026-11-01 00:00+00','2026-11-01 01:00+00','published');
insert into private.mcp_shift_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
insert into private.mcp_person_search_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18100000-0000-0000-0000-000000000003","session_id":"18100000-0000-0000-0000-000000000005"}',true);
insert into private.mcp_shift_update_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('mcp180-browser','mcp180-browser','18100000-0000-0000-0000-000000000001',now(),now()+interval '1 hour');
set constraints all immediate;
set constraints all deferred;
select set_config('test.first',private.prepare_mcp_shift_update('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008','2026-11-01 02:00+00','2026-11-01 03:00+00','[{"start_at":"2026-11-01T02:00:00Z","end_at":"2026-11-01T03:00:00Z","staffs":[{"staff_id":"18100000-0000-0000-0000-000000000007"}]}]')::text,true);
select set_config('test.stale',private.prepare_mcp_shift_update('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008','2026-11-01 04:00+00','2026-11-01 05:00+00','[{"start_at":"2026-11-01T04:00:00Z","end_at":"2026-11-01T05:00:00Z","staffs":[{"staff_id":"18100000-0000-0000-0000-000000000007"}]}]')::text,true);
select ok(has_function_privilege('authenticated','public.confirm_mcp_shift_update(uuid)','execute') and not has_function_privilege('mcp_import','public.confirm_mcp_shift_update(uuid)','execute'),'only the browser role can call confirmation');
select ok(not has_function_privilege('authenticated','private.confirm_mcp_shift_update(uuid)','execute') and not has_function_privilege('mcp_import','private.confirm_mcp_shift_update(uuid)','execute'),'confirmation primitive is not exposed');
select throws_ok($$select public.confirm_mcp_shift_update(current_setting('test.first')::uuid)$$,'42501','proposal_unavailable','OAuth cannot confirm');
select is((select start_at from public.shifts where id='18100000-0000-0000-0000-000000000008'),'2026-11-01 00:00+00'::timestamptz,'shift unchanged before confirmation');
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp180-browser"}',true);
select is(public.confirm_mcp_shift_update(current_setting('test.first')::uuid)->>'status','updated','browser confirmation updates shift');
select is((select start_at from public.shifts where id='18100000-0000-0000-0000-000000000008'),'2026-11-01 02:00+00'::timestamptz,'confirmed start is applied');
select is((select google_sync_status from public.shifts where id='18100000-0000-0000-0000-000000000008'),'pending_upsert','Google sync marked pending');
set constraints all immediate;
select is((select count(*) from public.notifications where user_id='18100000-0000-0000-0000-000000000009' and event_type='shift.assigned'),1::bigint,'confirmed update sends assignment notification');
select is((select count(*) from public.notifications where user_id='18100000-0000-0000-0000-000000000009' and event_type='shift.time_changed'),1::bigint,'confirmed update sends time-change notification');
set constraints all deferred;

select is(public.confirm_mcp_shift_update(current_setting('test.first')::uuid)->>'newly_updated','false','repeated confirmation is idempotent');
select is((select count(*) from public.audit_events where action_type='shift.update' and resource_id='18100000-0000-0000-0000-000000000008'),1::bigint,'exactly one success audit is written');
select throws_ok($$select public.confirm_mcp_shift_update(current_setting('test.stale')::uuid)$$,'22023','proposal_changed','stale proposal is rejected');
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18100000-0000-0000-0000-000000000003","session_id":"18100000-0000-0000-0000-000000000005"}',true);
insert into public.service_types(id,organization_id,name) values ('18100000-0000-0000-0000-000000000021','18100000-0000-0000-0000-000000000002','Synthetic service');
insert into public.staff_roles(id,organization_id,name) values ('18100000-0000-0000-0000-000000000022','18100000-0000-0000-0000-000000000002','Synthetic role');
select set_config('test.pending',private.prepare_mcp_shift_update('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008','2026-11-01 06:00+00','2026-11-01 07:00+00','[{"start_at":"2026-11-01T06:00:00Z","end_at":"2026-11-01T07:00:00Z","service_type_id":"18100000-0000-0000-0000-000000000021","staffs":[{"staff_id":"18100000-0000-0000-0000-000000000007","staff_role_id":"18100000-0000-0000-0000-000000000022"}]}]')::text,true);
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp180-browser"}',true);
update public.staffs set name='Renamed synthetic staff' where id='18100000-0000-0000-0000-000000000007';
select isnt((select private.mcp_shift_update_references(organization_id,shift_id,proposed_content->'segments') from private.mcp_shift_update_proposals where id=current_setting('test.pending')::uuid),(select reference_content from private.mcp_shift_update_proposals where id=current_setting('test.pending')::uuid),'stored display identities differ after staff rename');
select throws_ok($$select public.confirm_mcp_shift_update(current_setting('test.pending')::uuid)$$,'22023','proposal_changed','changed staff identity requires a new proposal');
update public.staffs set name='Synthetic staff' where id='18100000-0000-0000-0000-000000000007';
update public.organizations set name='Renamed synthetic organization' where id='18100000-0000-0000-0000-000000000002';
select throws_ok($$select public.confirm_mcp_shift_update(current_setting('test.pending')::uuid)$$,'22023','proposal_changed','changed organization identity requires a new proposal');
update public.organizations set name='Synthetic' where id='18100000-0000-0000-0000-000000000002';
update public.clients set name='Renamed synthetic client' where id='18100000-0000-0000-0000-000000000006';
select throws_ok($$select public.confirm_mcp_shift_update(current_setting('test.pending')::uuid)$$,'22023','proposal_changed','changed client identity requires a new proposal');
update public.clients set name='Synthetic client' where id='18100000-0000-0000-0000-000000000006';
update public.service_types set name='Renamed synthetic service' where id='18100000-0000-0000-0000-000000000021';
select throws_ok($$select public.confirm_mcp_shift_update(current_setting('test.pending')::uuid)$$,'22023','proposal_changed','changed service identity requires a new proposal');
update public.service_types set name='Synthetic service' where id='18100000-0000-0000-0000-000000000021';
update public.staff_roles set name='Renamed synthetic role' where id='18100000-0000-0000-0000-000000000022';
select throws_ok($$select public.confirm_mcp_shift_update(current_setting('test.pending')::uuid)$$,'22023','proposal_changed','changed role identity requires a new proposal');
update public.staff_roles set name='Synthetic role' where id='18100000-0000-0000-0000-000000000022';
update private.mcp_shift_update_controls set enabled=false where organization_id='18100000-0000-0000-0000-000000000002';
select throws_ok($$select public.confirm_mcp_shift_update(current_setting('test.pending')::uuid)$$,'42501','proposal_unavailable','disabled control prevents confirmation');
update private.mcp_shift_update_controls set enabled=true where organization_id='18100000-0000-0000-0000-000000000002';
update auth.oauth_consents set revoked_at=clock_timestamp() where id='18100000-0000-0000-0000-000000000004';
select throws_ok($$select public.confirm_mcp_shift_update(current_setting('test.pending')::uuid)$$,'42501','proposal_unavailable','revoked OAuth prevents confirmation');
update auth.oauth_consents set revoked_at=null where id='18100000-0000-0000-0000-000000000004';
savepoint overlapping_shift;
insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18100000-0000-0000-0000-000000000020','18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000006','2026-11-01 06:15+00','2026-11-01 06:30+00','published');
select throws_ok($$select public.confirm_mcp_shift_update(current_setting('test.pending')::uuid)$$,'23505','shift_conflict','overlapping shift prevents confirmation');
rollback to savepoint overlapping_shift;
create function pg_temp.reject_audit() returns trigger language plpgsql as $$begin raise exception 'synthetic audit failure'; end$$;
create trigger synthetic_audit_failure before insert on public.audit_events for each row execute function pg_temp.reject_audit();
select throws_ok($$select public.confirm_mcp_shift_update(current_setting('test.pending')::uuid)$$,'P0001','synthetic audit failure','audit failure aborts confirmation');
select is((select start_at from public.shifts where id='18100000-0000-0000-0000-000000000008'),'2026-11-01 02:00+00'::timestamptz,'audit failure rolls back shift update');
select is((select confirmed_at from private.mcp_shift_update_proposals where id=current_setting('test.pending')::uuid),null::timestamptz,'audit failure does not consume proposal');
select * from finish();
rollback;
